INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51011, 'Exodus 36:12', 'Exodus', 36, 12, 'همدارنګه هغوی پنځوس کړۍ ګانې په یوې پردې باندې او پنځوس د بلې جوړې په اخرنۍ پردې باندې په داسې ډول جوړې کړلې چې هغه کړۍ ګانې یو بل ته مخامخ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_12.mp3', '', 1761754199, 1761754199),
(51012, 'Exodus 36:13', 'Exodus', 36, 13, 'بیا هغوی پنځوس د سرو زرو چنګکونه جوړ کړل او د پردو د دوه جوړو په یوځای تړلو کې یې ورڅخه کار واخیست، ترڅو ټوله یوه خېمه ورڅخه جوړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_13.mp3', '', 1761754199, 1761754199),
(51013, 'Exodus 36:14', 'Exodus', 36, 14, 'هغوی د سپېڅلې خېمې د پوښ دپاره د وزو د وړیو څخه پردې جوړې کړې چې ټولې یوولس دانې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_14.mp3', '', 1761754199, 1761754199),
(51014, 'Exodus 36:15', 'Exodus', 36, 15, 'یوولس واړه پردې په یوه اندازه وې، یعنې دیارلس متره اوږدې او دوه متره پلنې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_15.mp3', '', 1761754199, 1761754199),
(51015, 'Exodus 36:16', 'Exodus', 36, 16, 'هغوی پنځه پردې په یوه جوړه کې سره یوځای کړې او نورې شپږ یې په بله جوړه کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_16.mp3', '', 1761754199, 1761754199),
(51016, 'Exodus 36:17', 'Exodus', 36, 17, 'بیا یې پنځوس کړۍ ګانې د یوې جوړې د اخرنۍ پردې په څنډه کې جوړې کړلې او د بلې جوړې د اخرنۍ پردې په څنډه کې یې همداسې جوړې کړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_17.mp3', '', 1761754199, 1761754199),
(51017, 'Exodus 36:18', 'Exodus', 36, 18, 'د برنجو پنځوس چنګکونه یې جوړ کړل او په کړۍ ګانو کې یې واچول چې خېمه یوځای سره وتړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_18.mp3', '', 1761754199, 1761754199),
(51018, 'Exodus 36:19', 'Exodus', 36, 19, 'بیا یې د خېمې دپاره د پسه د داسې پوستکي څخه پوښ جوړ کړ چې سور رنګ ورکړل شوی ؤ او په هغه باندې یې د ښې څرمنې څخه یو پوښ جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_19.mp3', '', 1761754199, 1761754199),
(51019, 'Exodus 36:20', 'Exodus', 36, 20, 'هغوی د خېمې دپاره د اکاسۍ د لرګي څخه ولاړ چوکاټونه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_20.mp3', '', 1761754199, 1761754199),
(51020, 'Exodus 36:21', 'Exodus', 36, 21, 'هر چوکاټ څلورنیم متره اوږد او پنځه شپېته سانتي پلن ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_21.mp3', '', 1761754199, 1761754199),
(51021, 'Exodus 36:22', 'Exodus', 36, 22, 'دوه یوشان نښلوونکې تختې یې درلودلې، ترڅو چوکاټونه سره یوځای شي. ټولو چوکاټونو دا تختې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_22.mp3', '', 1761754199, 1761754199),
(51022, 'Exodus 36:23', 'Exodus', 36, 23, 'هغوی د خېمې د جنوب خوا دپاره شل چوکاټونه جوړ کړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_23.mp3', '', 1761754199, 1761754199),
(51023, 'Exodus 36:24', 'Exodus', 36, 24, 'او څلوېښت د سپینو زرو پایې یې جوړې کړې چې ورلاندې شي، د هر چوکاټ لاندې دوه دوه پایې وې، د دې دپاره چې دوه تختې یې ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_24.mp3', '', 1761754199, 1761754199),
(51024, 'Exodus 36:25', 'Exodus', 36, 25, 'هغوی د بلې خوا یعنې د خېمې د شمال خوا دپاره شل چوکاټونه جوړ کړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_25.mp3', '', 1761754199, 1761754199),
(51025, 'Exodus 36:26', 'Exodus', 36, 26, 'او څلوېښت د سپینو زرو پایې یې جوړې کړلې چې د هر چوکاټ لاندې دوه دوه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_26.mp3', '', 1761754199, 1761754199),
(51026, 'Exodus 36:27', 'Exodus', 36, 27, 'د خېمې د شا دپاره یې چې د لوېدیځ خواته وه، شپږ چوکاټونه جوړ کړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_27.mp3', '', 1761754199, 1761754199),
(51027, 'Exodus 36:28', 'Exodus', 36, 28, 'او دوه چوکاټونه یې د خېمې د شاتني کنجونو دپاره جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_28.mp3', '', 1761754199, 1761754199),
(51028, 'Exodus 36:29', 'Exodus', 36, 29, 'په دغو دوو کنجونو کې هغه چوکاټونه د بېخ څخه نیولې تر سره پورې سره یوځای وو او په یوې کړۍ کې لګول شوي وو، دا دواړه یوشان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_29.mp3', '', 1761754199, 1761754199),
(51029, 'Exodus 36:30', 'Exodus', 36, 30, 'نو اته چوکاټونه او شپاړس د سپینو زرو پایې وې، د هر چوکاټ لاندې دوه دوه پایې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_30.mp3', '', 1761754199, 1761754199),
(51030, 'Exodus 36:31', 'Exodus', 36, 31, 'هغوی د اکاسۍ د لرګي څخه پنځلس اړمونه جوړ کړل، پنځه یې د هغو چوکاټونو دپاره جوړ کړل چې د خېمې په یوې خوا باندې وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_31.mp3', '', 1761754199, 1761754199),
(51031, 'Exodus 36:32', 'Exodus', 36, 32, 'پنځه د هغو چوکاټونو دپاره چې په بلې خوا باندې وو او پنځه د هغو چوکاټونو دپاره چې شاته د لوېدیځ خواته په اخر سر کې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_32.mp3', '', 1761754199, 1761754199),
(51032, 'Exodus 36:33', 'Exodus', 36, 33, 'منځنی اړم چې د چوکاټونو تر نیمایي پورې ایښودل شوی ؤ، هغه د خېمې د یو سر څخه تر بل سره پورې غزېدلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_33.mp3', '', 1761754199, 1761754199),
(51033, 'Exodus 36:34', 'Exodus', 36, 34, 'چوکاټونو ته یې د سرو زرو پوښ ورکړ او د سرو زرو کړیو سره یې ولګول چې اړمونه ونیسي. همدارنګه هغوی اړمونو ته هم د سرو زرو پوښ ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_34.mp3', '', 1761754199, 1761754199),
(51034, 'Exodus 36:35', 'Exodus', 36, 35, 'هغوی د ښه کتان او ابي، بانجاني او سرو وړیو څخه یوه پرده جوړه کړه او په هغې کې یې د اسماني مخلوقاتو نقشونه ګلدوزي کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_35.mp3', '', 1761754199, 1761754199),
(51035, 'Exodus 36:36', 'Exodus', 36, 36, 'د هغې دپاره یې د اکاسۍ د لرګي څخه څلور ستنې جوړې کړې او د سرو زرو پوښ یې ورته ورکړ او د هغو دپاره یې د سرو زرو چنګکونه جوړ کړل او څلور پایې یې ورته جوړې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_36.mp3', '', 1761754199, 1761754199),
(51036, 'Exodus 36:37', 'Exodus', 36, 37, 'هغوی د خېمې د دروازې دپاره د ابي، بانجاني او سرو وړیو او د ښه کتان څخه یوه پرده جوړه کړه چې ګلدوزي شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_37.mp3', '', 1761754199, 1761754199),
(51037, 'Exodus 36:38', 'Exodus', 36, 38, 'د دې پردې دپاره هغوی پنځه ستنې جوړې کړې چې د چنګکونو سره لګېدلې وې، د هغو سرونو او سیخونو ته یې د سرو زرو پوښ ورکړ او د ستنو دپاره یې پنځه برنجي پایې جوړې کړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_38.mp3', '', 1761754199, 1761754199),
(51038, 'Exodus 27:1', 'Exodus', 27, 1, 'د اکاسۍ د لرګي څخه د قربانۍ یو ځای جوړ کړه چې یو متر او دېرش سانتي لوړ وي. هغه دې څلور کنجه وي، دوه متره او شل سانتي دې اوږد وي او دوه متره او شل سانتي دې پلن وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_1.mp3', '', 1761754199, 1761754199),
(51039, 'Exodus 27:2', 'Exodus', 27, 2, 'د څلورو کنجونو دپاسه ښکرونه جوړ کړه، ترڅو ښکرونه او د قربانۍ ځای ټول د یوې ټوټې لرګي څخه جوړ شي او ټولو ته دې د برنجو پوښ ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_2.mp3', '', 1761754199, 1761754199),
(51040, 'Exodus 27:3', 'Exodus', 27, 3, 'د هغه ټول سامان د برنجو څخه جوړ کړه، یعنې د ایرو د لېرې کولو لوښي او د هغه بېلچې، د وینې د شیندلو کاسې، د غوښې قاشق پنجې او د اور لوښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_3.mp3', '', 1761754199, 1761754199),
(51041, 'Exodus 27:4', 'Exodus', 27, 4, 'یوه د برنجو جالۍ جوړه کړه او د هغې په څلورو کنجونو باندې څلور د برنجو کړۍ ګانې ولګوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_4.mp3', '', 1761754199, 1761754199),
(51042, 'Exodus 27:5', 'Exodus', 27, 5, 'دا جالۍ د قربانۍ د ځای د څنډې لاندې کېږده، ترڅو د قربانۍ د ځای تر نیمایي پورې ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_5.mp3', '', 1761754199, 1761754199),
(51043, 'Exodus 27:6', 'Exodus', 27, 6, 'د اکاسۍ د لرګي څخه د وړلو میلې جوړې کړه او د برنجو پوښ ورته ورکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_6.mp3', '', 1761754199, 1761754199),
(51044, 'Exodus 27:7', 'Exodus', 27, 7, 'او د وړلو په وخت کې یې د قربانۍ د ځای د دواړو اړخونو په کړیو کې ولګوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_7.mp3', '', 1761754199, 1761754199),
(51045, 'Exodus 27:8', 'Exodus', 27, 8, 'د هغې نقشې له مخې چې ما درته په غره باندې دروښودله، د قربانۍ ځای د تختو څخه جوړ کړه او تش یې پرېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_8.mp3', '', 1761754199, 1761754199),
(51046, 'Exodus 27:9', 'Exodus', 27, 9, 'د ښه کتان د پردو څخه د سپېڅلې خېمې دپاره یوه حوېلۍ جوړه کړه چې جنوب خوا یې پنځه څلوېښت متره اوږده وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_9.mp3', '', 1761754199, 1761754199),
(51047, 'Exodus 27:10', 'Exodus', 27, 10, 'هغه دې د برنجو په شلو پایو کې د شلو برنجي ستنو په وسیله د چنګکونو او سیخونو سره چې د سپینو زرو څخه جوړ شوي دي، ټینګه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_10.mp3', '', 1761754199, 1761754199),
(51048, 'Exodus 27:11', 'Exodus', 27, 11, 'د حوېلۍ شمال خوا دې هم همداسې جوړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_11.mp3', '', 1761754199, 1761754199),
(51049, 'Exodus 27:12', 'Exodus', 27, 12, 'د حوېلۍ لوېدیځې خواته به د لسو ستنو او پایو سره دوه ویشت متره اوږدې پردې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_12.mp3', '', 1761754199, 1761754199),
(51050, 'Exodus 27:13', 'Exodus', 27, 13, 'ختیځې خواته یعنې په هغه ځای کې چې د ننوتلو دروازه ده، هم باید حوېلۍ دوه ویشت متره پلنه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_13.mp3', '', 1761754199, 1761754199),
(51051, 'Exodus 27:16', 'Exodus', 27, 16, 'د حوېلۍ د دروازې دپاره دې یوه داسې پرده وي چې نهه متره اوږده وي. هغه دې د ابي، بانجاني او سرو وړیو او د ښه کتان څخه جوړه وي او د ګلدوزۍ کار دې په کې وشي. هغه دې د څلورو ستنو او څلورو پایو په وسیله ټینګه کړای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_16.mp3', '', 1761754199, 1761754199),
(51052, 'Exodus 27:17', 'Exodus', 27, 17, 'ټولې ستنې چې د حوېلۍ ګردچاپېره دي، د سپینو زرو د سیخونو سره دې ونښلول شي او چنګکونه یې باید د سپینو زرو څخه جوړ شي او پایې یې د برنجو څخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_17.mp3', '', 1761754199, 1761754199),
(51053, 'Exodus 27:18', 'Exodus', 27, 18, 'حوېلۍ دې پنځه څلوېښت متره اوږده او دوه ویشت متره پلنه وي. پردې دې د ښه کتان څخه جوړې شي چې دوه متره او شل سانتي لوړې وي او د برنجو پایې به هم ورسره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_18.mp3', '', 1761754199, 1761754199),
(51054, 'Exodus 27:19', 'Exodus', 27, 19, 'نور ټول سامان چې په خېمه کې ورڅخه کار اخیستل کیږي او هغه ټول موږي چې د خېمې او حوېلۍ دپاره دي، هغه دې د برنجو څخه جوړ شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_19.mp3', '', 1761754199, 1761754199),
(51055, 'Exodus 27:20', 'Exodus', 27, 20, 'اسراییلیانو ته امر وکړه چې د رڼا دپاره د زیتونو سوچه تېل راوړي، ترڅو څراغونه بل وساتل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_20.mp3', '', 1761754199, 1761754199),
(51056, 'Exodus 27:21', 'Exodus', 27, 21, 'په سپېڅلې خېمه کې د هغې پردې څخه دباندې چې د لوظ د صندوق په مخکې ده، هارون او د هغه زامن دې دا څراغونه د ماښام څخه نیولې تر سهاره پورې د څښتن په حضور کې بل وساتي. اسراییلیان او د هغوی اولاده دې د تل دپاره په دې حکم باندې عمل کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus27_verse_21.mp3', '', 1761754199, 1761754199),
(51057, 'Psalms 19:1', 'Psalms', 19, 1, 'اسمانونه څومره ښه بیانوي د خدای جلال کارنامې د لاس یې وایي فضا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_1.mp3', '', 1761754199, 1761754199),
(51058, 'Psalms 19:2', 'Psalms', 19, 2, 'هره ورځ یې اعلانوي راتلونکې ورځ ته هره شپه یې تکراروي سبا شپې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_2.mp3', '', 1761754199, 1761754199),
(51059, 'Psalms 19:3', 'Psalms', 19, 3, 'نه کوي هغوی خبرې نه اواز یې اورېدی شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_3.mp3', '', 1761754199, 1761754199),
(51060, 'Psalms 19:4', 'Psalms', 19, 4, 'خو بیاهم د دوی پیغام ټولې دنیا ته ور‌رسیږي د دوی خبرې د دنیا تر بل سره اورېدل کیږي خدای خېمه ده لګولې په اسمان کې لمر دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_4.mp3', '', 1761754199, 1761754199),
(51061, 'Psalms 19:5', 'Psalms', 19, 5, 'لمر راوځي لکه زوم د خپل مکانه لکه څنګه چې خوشحال وي یو اتل مسابقې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_5.mp3', '', 1761754199, 1761754199),
(51062, 'Psalms 19:6', 'Psalms', 19, 6, 'لمر راخېژي د اسمان له یوه سره او رسیږي تر بل سره هېڅ شی پټ نه دی د هغه له ګرمۍ نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_6.mp3', '', 1761754199, 1761754199),
(51063, 'Psalms 19:7', 'Psalms', 19, 7, 'د څښتن شریعت کامل دی او تازه کوي روح باوري دي ټول حکمونه د څښتن ورکوي حکمت هغو ته چې ساده دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_7.mp3', '', 1761754199, 1761754199),
(51064, 'Psalms 19:8', 'Psalms', 19, 8, 'دي سم د څښتن اصول د خلکو زړونو ته خوښي ورکوي پاک دي حکمونه د څښتن ورکوي ذهن ته پوهه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_8.mp3', '', 1761754199, 1761754199),
(51065, 'Psalms 19:9', 'Psalms', 19, 9, 'وېره ښه ده له څښتنه برقرار به وي مدام د څښتن قضاوتونه دي برحقه او همېش عادلانه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_9.mp3', '', 1761754199, 1761754199),
(51066, 'Psalms 19:10', 'Psalms', 19, 10, 'ده په زړه پورې د سوچه طلا نه ډېره هغه ډېره خوږه ده د سوچه شاتو نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_10.mp3', '', 1761754199, 1761754199),
(51067, 'Psalms 19:11', 'Psalms', 19, 11, 'ورکوي هغه اخطار د ستا خادم ته که یې ومنم نو مومم به لوی اجر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_11.mp3', '', 1761754199, 1761754199),
(51068, 'Psalms 19:12', 'Psalms', 19, 12, 'نه شي څوک کولای چې په خپله خطا پوه شي معاف کړه ای څښتنه خطاګانې نامعلومه مې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_12.mp3', '', 1761754199, 1761754199),
(51069, 'Psalms 19:13', 'Psalms', 19, 13, 'نو قصدي ګناه نه ما خوندي وساته پرې یې نږدې چې په ما شي مسلطه او بیا زه به شم کامل شم به خلاص له ګناهونو لویو لویو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_13.mp3', '', 1761754199, 1761754199),
(51070, 'Psalms 19:14', 'Psalms', 19, 14, 'ای څښتنه، ای زما د پناه ځایه! ای زما ژغورونکیه! شي منظورې دې خبرې او فکرونه زما تاته!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms19_verse_14.mp3', '', 1761754199, 1761754199),
(51071, 'Exodus 10:1', 'Exodus', 10, 1, 'بیا څښتن موسی ته وویل: «فرعون ته ورشه، ځکه چې ما د هغه او د هغه د درباریانو زړونه سخت کړي دي، ترڅو هغوی ته خپلې معجزې وښایم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_1.mp3', '', 1761754199, 1761754199),
(51072, 'Exodus 10:2', 'Exodus', 10, 2, 'او د دې دپاره چې تاسو وکولای شئ خپلو اولادونو او لمسیو ته ووایئ چې څنګه مې د معجزو په ښودلو سره د مصریانو څخه کم عقلان جوړ کړل، نو بیا به تاسو ټول پوه شئ چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_2.mp3', '', 1761754199, 1761754199),
(51073, 'Exodus 10:3', 'Exodus', 10, 3, 'نو موسی او هارون فرعون ته ورغلل او ورته ویې ویل: «د عبرانیانو څښتن خدای داسې وایي: ته به ترڅو پورې ماته نه تسلیمېږې؟ زما قوم پرېږده چې لاړ شي او زما عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_3.mp3', '', 1761754199, 1761754199),
(51074, 'Exodus 10:4', 'Exodus', 10, 4, 'که چېرې ته د هغوی د پرېښودلو څخه انکار وکړې، زه به سبا ستا په هېواد باندې ملخان نازل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_4.mp3', '', 1761754199, 1761754199),
(51075, 'Exodus 10:5', 'Exodus', 10, 5, 'هغوی به د ځمکې مخ پټ کړي او ځمکه به نه ښکاري. هرڅه چې د ږلۍ څخه پاتې شوي دي هغه به وخوري، حتی هغه ونې چې پاتې شوې دي هغه به هم وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_5.mp3', '', 1761754199, 1761754199),
(51076, 'Exodus 10:6', 'Exodus', 10, 6, 'ستا کورونه، ستا د ټولو درباریانو او ستا د ټول قوم کورونه به د ملخانو څخه ډک شي. دا به د هغو شیانو څخه ډېر بد وي کوم چې ستاسو نیکونو د دې وطن په تاریخ کې لیدلي دي.» بیا موسی د فرعون څخه لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_6.mp3', '', 1761754199, 1761754199),
(51077, 'Exodus 10:7', 'Exodus', 10, 7, 'فرعون ته خپلو درباریانو وویل: «ترڅه وخته پورې به دا سړی مونږ ته تکلیف راکوي؟ د اسراییلو خلک پرېږده چې لاړ شي، ترڅو وکولای شي د خپل څښتن خدای عبادت وکړي. ته خبر نه یې چې مصر وران شوی دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_7.mp3', '', 1761754199, 1761754199),
(51078, 'Exodus 10:8', 'Exodus', 10, 8, 'موسی او هارون یې بېرته فرعون ته راوستل او فرعون هغوی ته وویل: «تاسو لاړ شئ او د خپل څښتن خدای عبادت وکړئ. خو څوک څوک به لاړ شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_8.mp3', '', 1761754199, 1761754199),
(51079, 'Exodus 10:9', 'Exodus', 10, 9, 'موسی په ځواب کې وویل: «مونږ ټول به د ځوانانو او سپین ږیرو سره لاړ شو. مونږ به خپل زامن، لورګانې، رمې او پادې هم د ځان سره بوځو، ځکه مونږ غواړو چې څښتن ته د درناوي په خاطر جشن ونیسو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_9.mp3', '', 1761754199, 1761754199),
(51080, 'Exodus 10:10', 'Exodus', 10, 10, 'فرعون وویل: «زه په څښتن باندې قسم خورم چې تاسو به هېڅکله پرېنږدم چې خپلې ښځې او اولادونه د ځان سره بوځئ! دا ښکاره خبره ده چې تاسو کوم بد نیت لرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_10.mp3', '', 1761754199, 1761754199),
(51081, 'Exodus 10:11', 'Exodus', 10, 11, 'نه! یوازې سړي دې لاړ شي او د څښتن عبادت دې وکړي، ځکه چې دا ستا غوښتنه ده.» بیا موسی او هارون د فرعون د حضور څخه وشړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_11.mp3', '', 1761754199, 1761754199),
(51082, 'Exodus 10:12', 'Exodus', 10, 12, 'څښتن موسی ته وویل: «خپل لاس دې د مصر په خاوره باندې پورته کړه چې د ملخانو بلا راشي او هرڅه چې د ږلۍ څخه شنه پاتې شوي دي، هغه وخوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_12.mp3', '', 1761754199, 1761754199),
(51083, 'Exodus 10:13', 'Exodus', 10, 13, 'نو موسی خپله امسا پورته کړه او څښتن د ختیځ له خوا په مصر باندې د یوې شپې او ورځې دپاره باد راوالوزاوه او د سهار په وخت کې یې ملخان د ځان سره راوړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_13.mp3', '', 1761754199, 1761754199),
(51084, 'Exodus 10:14', 'Exodus', 10, 14, 'دې ملخانو د مصر ټول وطن ونیوه او دومره زیات وو چې داسې بلا نه چا لیدلې وه او نه به یې کله وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_14.mp3', '', 1761754199, 1761754199),
(51085, 'Exodus 10:15', 'Exodus', 10, 15, 'ځمکه په ملخانو باندې داسې پټه شوه چې توره ښکاره کېدله. هرڅه چې د ږلۍ څخه پاتې شوي وو هغه یې وخوړل چې په هغو کې د ونو مېوې هم شاملې وې. یو شین بوټی او یا ونه هم د مصر په ځمکه کې پاتې نه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_15.mp3', '', 1761754199, 1761754199),
(51086, 'Exodus 10:16', 'Exodus', 10, 16, 'فرعون زر موسی او هارون راوغوښتل او ورته ویې ویل: «ما ستاسو د څښتن خدای او ستاسو په وړاندې ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_16.mp3', '', 1761754199, 1761754199),
(51087, 'Exodus 10:17', 'Exodus', 10, 17, 'اوس یوځل بیا زما ګناه وبخښئ او خپل څښتن خدای ته دعا وکړئ چې زما څخه دا وژونکې بلا لېرې کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_17.mp3', '', 1761754199, 1761754199),
(51088, 'Exodus 10:18', 'Exodus', 10, 18, 'موسی د فرعون څخه لاړ او څښتن ته یې دعا وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_18.mp3', '', 1761754199, 1761754199),
(51089, 'Exodus 10:19', 'Exodus', 10, 19, 'څښتن د ختیځ باد په یو سخت لوېدیځ باد باندې بدل کړ. دغه باد ملخان سرې بحیرې ته یووړل او په ټول مصر کې یو ملخ هم پاتې نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_19.mp3', '', 1761754199, 1761754199),
(51090, 'Exodus 10:20', 'Exodus', 10, 20, 'خو څښتن د فرعون زړه سخت کړ او هغه اسراییلیان پرېنښودل چې لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_20.mp3', '', 1761754199, 1761754199),
(51091, 'Exodus 10:21', 'Exodus', 10, 21, 'بیا څښتن موسی ته وویل: «خپل لاس د اسمان خواته پورته کړه، ترڅو د مصر په خاوره باندې توره تیاره راشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_21.mp3', '', 1761754199, 1761754199),
(51092, 'Exodus 10:22', 'Exodus', 10, 22, 'نو موسی خپل لاس د اسمان خواته پورته کړ او په مصر باندې د درېو ورځو دپاره توره تیاره شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_22.mp3', '', 1761754199, 1761754199),
(51093, 'Exodus 10:23', 'Exodus', 10, 23, 'مصریانو نه شو کولای چې یو بل وویني او هېڅوک هم په هغه وخت کې د خپل کور څخه ونه وت. خو چېرته چې اسراییلیان اوسېدل هلته رڼا وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_23.mp3', '', 1761754199, 1761754199),
(51094, 'Exodus 10:24', 'Exodus', 10, 24, 'بیا فرعون موسی راوغوښت او ورته ویې ویل: «لاړ شئ او د څښتن عبادت وکړئ. حتی ستاسو ښځې او ماشومان هم تاسو سره تللی شي. خو یوازې خپلې رمې او پادې پرېږدئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_24.mp3', '', 1761754199, 1761754199),
(51095, 'Exodus 10:25', 'Exodus', 10, 25, 'موسی وویل: «ته باید مونږ ته د دې اجازه راکړې چې د ځان سره خپل حیوانات بوځو چې خپل څښتن خدای ته قربانۍ او سوځېدونکې نذرانې وړاندې کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_25.mp3', '', 1761754199, 1761754199),
(51096, 'Exodus 10:26', 'Exodus', 10, 26, 'نه، مونږ به د ځان سره خپل حیوانات خامخا د ځان سره بوځو او یو حیوان به هم پاتې نه شي. مونږ به په خپله هغه غوره کوو چې له هغو څخه د خپل څښتن خدای په عبادت کې کار واخلو. ترڅو پورې چې هلته نه یو رسېدلي مونږ نه پوهېږو چې کوم حیوانات هغه ته قرباني کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_26.mp3', '', 1761754199, 1761754199),
(51097, 'Exodus 10:27', 'Exodus', 10, 27, 'خو څښتن د فرعون زړه سخت کړ او هغه راضي نه ؤ چې هغوی تګ ته پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_27.mp3', '', 1761754199, 1761754199),
(51098, 'Exodus 10:28', 'Exodus', 10, 28, 'فرعون موسی ته وویل: «زما له مخې څخه لېرې شه! بیا زما د لیدلو هڅه ونه کړې! که چېرې بیا زما سره مخامخ شوې، نو په هماغه ورځ به ووژل شې!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_28.mp3', '', 1761754199, 1761754199),
(51099, 'Exodus 10:29', 'Exodus', 10, 29, 'موسی په ځواب کې وویل: «ته رښتیا وایې، زه به بیا هېڅکله تا ونه وینم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus10_verse_29.mp3', '', 1761754199, 1761754199),
(51100, 'Judges 6:1', 'Judges', 6, 1, 'د اسراییلو قوم یوځل بیا داسې کارونه وکړل چې د څښتن په نظر کې بد وو، نو څښتن د مدیانیانو قوم پرېښود چې په هغوی باندې اووه کاله حکومت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_1.mp3', '', 1761754199, 1761754199),
(51101, 'Judges 6:2', 'Judges', 6, 2, 'مدیانیان دومره ظالمان وو چې د اسراییلو خلک د هغوی څخه په سمڅو او د غونډیو په نورو خوندي ځایونو کې پټېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_2.mp3', '', 1761754199, 1761754199),
(51102, 'Judges 6:3', 'Judges', 6, 3, 'هرکله چې به اسراییلیانو خپل فصلونه کرل، نو مدیانیان، عمالیقیان او د دښتې د قبیلو خلک به راتلل او په هغوی باندې به یې حمله کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_3.mp3', '', 1761754199, 1761754199),
(51103, 'Judges 6:4', 'Judges', 6, 4, 'دوی په هغه ځمکه کې خېمې ودرولې او د ځمکې حاصلات به یې تر غزې پورې له منځه وړل. د هغوی څخه به یې ټول پسونه، غویان او خره بېول او د اسراییلیانو دپاره یې هېڅ شی پرېنښود چې ژوند ورباندې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_4.mp3', '', 1761754199, 1761754199),
(51104, 'Judges 6:5', 'Judges', 6, 5, 'هغوی به د خپلو څارویو او خېمو سره لکه د ملخانو په شان راتلل. هغوی او د هغوی د اوښانو شمېر دومره زیات ؤ چې حساب یې نه شو کېدلی. دوی به راتلل او ځمکه به یې ویجاړوله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_5.mp3', '', 1761754199, 1761754199),
(51105, 'Judges 6:6', 'Judges', 6, 6, 'او اسراییلیان د هغوی په وړاندې بې وسه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_6.mp3', '', 1761754199, 1761754199),
(51106, 'Judges 6:7', 'Judges', 6, 7, 'نو د اسراییلو قوم د مدیانیانو په خلاف څښتن ته د مرستې دپاره فریاد وکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_7.mp3', '', 1761754199, 1761754199),
(51107, 'Judges 6:8', 'Judges', 6, 8, 'او هغه ورته یو پیغمبر راولېږه چې هغوی ته یې د اسراییلو د څښتن خدای له خوا دا پیغام راوړ: «ما تاسو د مصر یعنې د هغه هېواد څخه چې په کې غلامان وئ، راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_8.mp3', '', 1761754199, 1761754199),
(51108, 'Judges 6:9', 'Judges', 6, 9, 'تاسو مې د مصریانو او هغو ټولو خلکو څخه چې په دې خاوره کې یې په تاسو باندې ظلم کاوه، وژغورلئ. هغوی مې ستاسو د مخې څخه لېرې کړل او د هغوی ځمکه مې تاسو ته درکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_9.mp3', '', 1761754199, 1761754199),
(51109, 'Judges 6:10', 'Judges', 6, 10, 'تاسو ته مې وویل چې زه ستاسو څښتن خدای یم او که څه هم تاسو د اموریانو په خاوره کې اوسېږئ، خو د هغوی د خدایانو عبادت مه کوئ. خو تاسو زما خبرو ته غوږ ونه نیوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_10.mp3', '', 1761754199, 1761754199),
(51110, 'Judges 6:11', 'Judges', 6, 11, 'یوه ورځ د څښتن فرښته د عفره کلي ته راغله او د څېړۍ د ونې لاندې چې د یوآش ابیعزري ونه وه کښېناستله. د یوآش زوی جدعون په پټه د انګورو د شربت ویستلو په خم کې غنم ټکول چې مدیانیان یې ونه ویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_11.mp3', '', 1761754199, 1761754199);